CREATE TRIGGER IF NOT EXISTS validate_android_certs_0 BEFORE INSERT ON ecosystem_apps
   WHEN json_valid(NEW.android_cert_sha256) = 0 OR json_type(NEW.android_cert_sha256) != 'array'
